function openSidebar(){const sidebar=$('#sidebar'),backdrop=$('#sidebar-backdrop'),button=$('#menu-button');if(!sidebar||!backdrop)return;backdrop.hidden=false;sidebar.classList.add('open');sidebar.setAttribute('aria-hidden','false');requestAnimationFrame(()=>backdrop.classList.add('show'));document.body.classList.add('menu-open');button?.setAttribute('aria-expanded','true')}
