function bindGlobal(){
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-route]');if(nav){navigate(nav.dataset.route);closeSidebar()}
  });
  const menuButton=$('#menu-button');menuButton?.setAttribute('aria-expanded','false');menuButton?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggleSidebar()});
  $('#global-search-button').onclick=openGlobalSearch;
  $('#global-search-close').onclick=()=>$('#command-dialog').close();
  $('#global-search-input').oninput=debounce(e=>renderGlobalSearch(e.target.value),80);
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openGlobalSearch()}});
  $('#sidebar-close').onclick=closeSidebar;
  $('#sidebar-backdrop').onclick=closeSidebar;
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSidebar()});
  window.addEventListener('resize',()=>{if(window.innerWidth>820)closeSidebar()});
  $('#theme-toggle').onclick=()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();applyTheme();render()};
  $('#timer-mini').onclick=()=>$('#timer-dialog').showModal();
  $('#timer-start').onclick=startTimer;$('#timer-pause').onclick=pauseTimer;$('#timer-finish').onclick=finishTimer;
  window.addEventListener('hashchange',()=>navigate(location.hash.replace('#/','')||'dashboard',false));
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install-button').hidden=false});
  $('#install-button').onclick=async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#install-button').hidden=true};
  $('#import-confirm').onclick=importBackup;
}
