  $$('[data-search-course]',box).forEach(b=>b.onclick=()=>{$('#command-dialog').close();openLesson(b.dataset.searchCourse)});
  $$('[data-search-edital]',box).forEach(b=>b.onclick=()=>{const item=DATA.edital.find(x=>x.id===b.dataset.searchEdital);editalSearchPrefill=item?item.conteudo:'';$('#command-dialog').close();navigate('edital')});
