  const add=(subject,topicId,questions,correct)=>{questions=Math.max(0,Number(questions||0));correct=clamp(Number(correct||0),0,questions);if(!questions||!subject)return;subjects[subject]??={subject,prova:proofOfSubject(subject),questions:0,correct:0,errors:0,weight:DATA.weights[subject]||0};subjects[subject].questions+=questions;subjects[subject].correct+=correct;subjects[subject].errors+=questions-correct;if(topicId){const item=DATA.edital.find(x=>x.id===topicId);if(item&&['P1','P2'].includes(item.prova)){topics[topicId]??={topicId,prova:item.prova,subject:item.materia,item:item.item,label:item.conteudo,topicWeight:Number(item.pesoTopico||0),questions:0,correct:0,errors:0,weight:DATA.weights[item.materia]||0};topics[topicId].questions+=questions;topics[topicId].correct+=correct;topics[topicId].errors+=questions-correct;}}};
  DATA.edital.filter(x=>['P1','P2'].includes(x.prova)).forEach(x=>{const st=statusEdital(x.id);add(x.materia,x.id,st.questions,st.correct)});
