  return{editalDone,editalDoneRatio:editalDone/DATA.edital.length,courseTotalSec,courseDoneSec,courseDoneRatio:courseTotalSec?courseDoneSec/courseTotalSec:0,watchedCount,questions:qa.totalQuestions,correct:qa.totalCorrect,errors:qa.totalErrors,accuracy:qa.accuracy,timerSec};
