function scheduleEventTask(e){
  if(e.type==='lesson')return `<div class="task lesson-task ${eventDone(e)?'done':''}" data-open-lesson="${e.lessonId}"><button class="check-btn ${eventDone(e)?'on':''}" data-toggle-event="${e.id}" title="Marcar aula como assistida">✓</button><div class="task-copy"><strong>${esc(e.materia)} · Tópico ${esc(e.topico)} · Aula ${esc(e.numero)}</strong><span>${esc(e.titulo)}</span><small>${formatTimeOfDay(e.startMinute)}–${formatTimeOfDay(e.endMinute)} · ${esc(e.professor||'Responsável não informado')}</small></div><div class="task-side"><span class="task-time">${e.fixed&&e.plannedMinutes?minutesToClock(e.plannedMinutes):secondsToClock(e.duracaoSegundos)}</span>${state.lessonLinks?.[e.lessonId]?`<button class="tiny-link" data-open-material="${e.lessonId}" title="Abrir link direto do material">Abrir ↗</button>`:''}</div></div>`;
  return `<div class="task practice-task ${eventDone(e)?'done':''} ${e.finalSprint||e.smart?'smart-practice':''} ${e.complement?'complement-practice':''}" data-practice-route="${esc(e.route||'hoje')}" data-practice-subject="${esc(e.subject||'')}" data-practice-topic="${esc(e.topicId||'')}"><button class="check-btn ${eventDone(e)?'on':''}" data-toggle-event="${e.id}">✓</button><div class="task-copy"><strong>${esc(e.materia)}</strong><span>${esc(e.titulo)}</span><small>${formatTimeOfDay(e.startMinute)}–${formatTimeOfDay(e.endMinute)} · ${e.complement?'Complemento do edital':e.fixed?'Bloco do plano diário':e.smart?'Priorizado pelos seus erros':'Bloco de prática'}</small></div><span class="task-time">${minutesToClock(e.endMinute-e.startMinute)}</span></div>`
}
function bindScheduleTasks(events,rerender){
  $$('[data-toggle-event]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();const item=events.find(x=>x.id===b.dataset.toggleEvent);if(item){toggleEventDone(item);rerender()}});
  $$('[data-open-lesson]').forEach(el=>el.onclick=()=>openLesson(el.dataset.openLesson));
  $$('[data-open-material]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();openLesson(b.dataset.openMaterial,true)});
  $$('[data-practice-route]').forEach(el=>el.onclick=ev=>{if(ev.target.closest('[data-toggle-event]'))return;const target=events.find(x=>x.id===el.querySelector('[data-toggle-event]')?.dataset.toggleEvent);if(el.dataset.practiceRoute==='questoes'){questionPrefill={subject:el.dataset.practiceSubject||target?.subject||'',topicId:el.dataset.practiceTopic||target?.topicId||''};}navigate(el.dataset.practiceRoute)});
}
function courseBySubject(){const o={};objectiveSubjects().forEach(s=>o[s]={total:0,done:0});DATA.course.forEach(x=>{if(!o[x.materia])return;o[x.materia].total+=x.duracaoSegundos;if(statusCourse(x.id).watched)o[x.materia].done+=x.duracaoSegundos});return o}
function lessonProgress(m){const g=courseBySubject()[m];return g&&g.total?g.done/g.total:0}

